22:## Blocking questions (user)
32:## Hypotheses (prudent default, no question)
86:## Steps (TDD — tests first; each step green and mergeable alone)
91:### Step 1 — Parse docker's `Status`; one age format · S (Q1-A)
126:### Step 2 — Activity column, observed states, row spinner removed, blink · M (after 1; Q2, Q3, Q4)
177:### Step 3 — Footer of the selected row, help legend · S (after 2)
209:### Step 4 — Guards and documentation · S (after 2–3; docs can be written alongside step 3)
246:## Order and parallelism
251:## Risks / irreversible points
	var line strings.Builder
	for _, col := range cols {
		if col.Width <= 0 {
			continue
		}
		// A header is cut at its end whatever the column asks for its values: a
		// title is recognised by how it starts, and TruncateHead is a statement
		// about the data.
		line.WriteString(m.styles.Header.Render(fit(col.Title, col.Width, false)))
	}
	return line.String()
}

// rowLine renders one row.
//
// A busy row shows the spinner in its status column instead of that column's
// own cell — on the selected row too. The glyph is the primary signal, and a
// signal that disappears under the cursor is one the user loses exactly when
// they are looking at it.
func (m *Model[T]) rowLine(cols []table.Column, item T, selected bool) string {
	_, busy := m.busyLabel(item)

	var line strings.Builder
	for i, c := range m.cfg.Columns {
		if i >= len(cols) || cols[i].Width <= 0 {
			continue
		}
		state := indicator.Idle
		if c.Indicator != nil {
			state = m.indicatorState(c, item, busy)
		}
		text := c.Cell(item)
		switch {
		case state != indicator.Idle:
			text = indicator.Glyph(state, m.blinkOn)
		case busy && m.indicatorAt < 0 && i == m.cfg.StatusColumn:
			text = m.spinnerFrame
		}
		if state != indicator.Idle {
			// Padded with runewidth, not lipgloss: lipgloss always counts an
			// ambiguous-width glyph as one cell, runewidth follows the terminal.
			fitted := runewidth.FillRight(text, cols[i].Width)
			line.WriteString(m.indicatorCellStyle(state, selected).Render(fitted))
			continue
		}
		fitted := fit(text, cols[i].Width, c.TruncateHead)
		if !busy && (!selected || m.preserveColumnColors) {
			if runs, ok := m.multiRunCell(c, item, fitted, selected); ok {
				line.WriteString(runs)
				continue
			}
		}
		line.WriteString(m.cellStyle(c, item, selected, busy, i).Render(fitted))
	}
